SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name FROM song_masters sm JOIN albums a ON a.id=sm.album_id WHERE sm.album_id!='pending-uploads' AND lower(trim(sm.title)) IN ('徵羽摩柯 , 机器人的悲伤 - robotic sorrow','心上秋','心碎犯','心碎犯-inst','心空华梦','心空华梦remix','恋爱废物就是我','恶犬','悲伤的逗乐者','想和你多一点','我仅剩的灵魂','我是如此地','我被浸泡在每一颗水里','我认识一个人','所以我戴上了耳机','手冷','拉文克劳印象曲','拉文克劳印象曲·伴奏','挚鸣致夏','摇滚解体','摘花','摩羯座','放任雨落·rewritten(feat.雨令,令雨)','数风流','斯莱特林印象曲','斯莱特林印象曲·伴奏','无拘的秘信(feat.yari riako,karandox lopez)','日暮晚风','日月灯','早安，午安，晚安','早安，午安，晚安·伴奏','时光','时间的彼端','易水诀','星空的孩子') ORDER BY sm.title,sm.album_id